ype": "text", "style": {"color": "#b45309", "fontSize": 16, "fontWeight": 700}, "width": 210, "height": 25, "zIndex": 31, "frameId": "frame_page_1"}, {"x": 558, "y": 286, "id": "el_kpi3_sub_p1", "data": {"text": "Prejuízo + Vencido"}, "type": "text", "style": {"color": "#94a3b8", "fontSize": 9}, "width": 210, "height": 15, "zIndex": 32, "frameId": "frame_page_1"}, {"x": 40, "y": 330, "id": "el_score_header_icon_p1", "data": {"name": "Activity", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#334155", "background": "transparent", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 8}, "width": 28, "height": 28, "zIndex": 33, "frameId": "frame_page_1"}, {"x": 78, "y": 336, "id": "el_score_header_text_p1", "data": {"text": "SCORE DE CRÉDITO"}, "type": "text", "style": {"color": "#334155", "fontSize": 13, "fontWeight": 700}, "width": 150, "height": 20, "zIndex": 34, "frameId": "frame_page_1"}, {"x": 212, "y": 344, "id": "el_score_header_div_p1", "data": {}, "type": "divider", "style": {"background": "#e2e8f0"}, "width": 562, "height": 2, "zIndex": 35, "frameId": "frame_page_1"}, {"x": 40, "y": 365, "id": "el_score_card_bg_p1", "data": {}, "type": "container", "style": {"background": "#ffffff", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 12}, "width": 734, "height": 680, "zIndex": 36, "frameId": "frame_page_1"}, {"x": 60, "y": 370, "id": "el_score_headline_p1", "data": {"text": "Como o mercado enxerga seu CPF hoje (e o que está travando seu crédito)"}, "type": "text", "style": {"color": "#0f172a", "fontSize": 15, "fontWeight": 700}, "width": 694, "height": 23, "zIndex": 37, "frameId": "frame_page_1"}, {"x": 60, "y": 400, "id": "el_score_subtitle_p1", "data": {"text": "Seu Score é uma estimativa de chance de pagar em dia nos próximos 6 meses. Quanto maior a pontuação, maior tende a ser a facilidade para conseguir crédito e melhores condições.\\n\\n"}, "type": "text", "style": {"color": "#64748b", "fontSize": 10}, "width": 733, "height": 45, "zIndex": 38, "frameId": "frame_page_1"}, {"x": 70, "y": 430, "id": "el_score_speedometer_p1", "data": {"text": "html:<div style='position:relative;width:100%;text-align:center;'><svg viewBox='0 0 200 110' style='width:100%;height:105px;display:block;'><path d='M 20 90 A 80 80 0 0 1 180 90' fill='none' stroke='#e5e7eb' stroke-width='14' stroke-linecap='round' /><path d='M 20 90 A 80 80 0 0 1 35.28 42.98' fill='none' stroke='#ef4444' stroke-width='14' stroke-linecap='round' /><path d='M 35.28 42.98 A 80 80 0 0 1 75.28 13.91' fill='none' stroke='#f97316' stroke-width='14' stroke-linecap='round' /><path d='M 75.28 13.91 A 80 80 0 0 1 124.72 13.91' fill='none' stroke='#eab308' stroke-width='14' stroke-linecap='round' /><path d='M 124.72 13.91 A 80 80 0 0 1 164.72 42.98' fill='none' stroke='#84cc16' stroke-width='14' stroke-linecap='round' /><path d='M 164.72 42.98 A 80 80 0 0 1 180 90' fill='none' stroke='#22c55e' stroke-width='14' stroke-linecap='round' /><circle cx='{{100 - 80 * cos($SCORE_CREDITO[0].score * 0.00314159265)}}' cy='{{90 - 80 * sin($SCORE_CREDITO[0].score * 0.00314159265)}}' r='7' fill='{{if($SCORE_CREDITO[0].score <= 200, '#ef4444', if($SCORE_CREDITO[0].score <= 400, '#f97316', if($SCORE_CREDITO[0].score <= 600, '#eab308', if($SCORE_CREDITO[0].score <= 800, '#84cc16', '#22c55e'))))}}' stroke='#fff' stroke-width='2' /><circle cx='{{100 - 80 * cos($SCORE_CREDITO[0].score * 0.00314159265)}}' cy='{{90 - 80 * sin($SCORE_CREDITO[0].score * 0.00314159265)}}' r='3' fill='#fff' /><line x1='100' y1='90' x2='{{100 - 80 * cos($SCORE_CREDITO[0].score * 0.00314159265)}}' y2='{{90 - 80 * sin($SCORE_CREDITO[0].score * 0.00314159265)}}' stroke='{{if($SCORE_CREDITO[0].score <= 200, '#ef4444', if($SCORE_CREDITO[0].score <= 400, '#f97316', if($SCORE_CREDITO[0].score <= 600, '#eab308', if($SCORE_CREDITO[0].score <= 800, '#84cc16', '#22c55e'))))}}' stroke-width='2.5' stroke-linecap='round' /><circle cx='100' cy='90' r='6' fill='#fff' stroke='#e2e8f0' stroke-width='1' /><circle cx='100' cy='90' r='2' fill='#94a3b8' /><text x='15' y='110' font-size='10' fill='#94a3b8' font-weight='700'>0</text><text x='165' y='110' font-size='10' fill='#94a3b8' font-weight='700'>1000</text></svg></div>"}, "type": "text", "style": {}, "width": 175, "height": 105, "zIndex": 39, "frameId": "frame_page_1"}, {"x": 260, "y": 452.6592184, "id": "el_score_det_icon1_p1", "data": {"name": "TrendingUp", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#ec4899", "padding": 3, "background": "#fafafa38", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 6}, "width": 28, "height": 28, "zIndex": 40, "frameId": "frame_page_1"}, {"x": 298, "y": 450.6592184, "id": "el_score_det_text1_p1", "data": {"text": "html:<span style='font-size:11px;font-weight:600;color:#1e293b;font-family:sans-serif;'>Métrica do Score: <span style='color:{{if($SCORE_CREDITO[0].score <= 200, '#ef4444', if($SCORE_CREDITO[0].score <= 400, '#f97316', if($SCORE_CREDITO[0].score <= 600, '#eab308', if($SCORE_CREDITO[0].score <= 800, '#84cc16', '#22c55e'))))}};'>{{if($SCORE_CREDITO[0].score <= 200, 'Péssimo', if($SCORE_CREDITO[0].score <= 400, 'Ruim', if($SCORE_CREDITO[0].score <= 600, 'Regular', if($SCORE_CREDITO[0].score <= 800, 'Bom', 'Ótimo'))))}} ({{if($SCORE_CREDITO[0].score <= 200, '0 a 200', if($SCORE_CREDITO[0].score <= 400, '201 a 400', if($SCORE_CREDITO[0].score <= 600, '401 a 600', if($SCORE_CREDITO[0].score <= 800, '601 a 800', '801 a 1000'))))}})</span></span><br/><span style='color:#64748b;font-family:sans-serif;'>{{if($SCORE_CREDITO[0].score <= 200, 'Risco muito alto. Regularização recomendada.', if($SCORE_CREDITO[0].score <= 400, 'Risco alto. Negociação pode melhorar o perfil.', if($SCORE_CREDITO[0].score <= 600, 'Risco moderado. Valide renda e estabilidade.', if($SCORE_CREDITO[0].score <= 800, 'Risco baixo. Perfil favorável ao crédito.', 'Risco muito baixo. Excelente predisposição.'))))}}</span>"}, "type": "text", "style": {"fontSize": 10, "lineHeight": 1.4}, "width": 440, "height": 29, "zIndex": 41, "frameId": "frame_page_1"}, {"x": 260, "y": 497.6592184, "id": "el_score_det_icon2_p1", "data": {"name": "ClipboardCheck", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#10b981", "padding": 3, "background": "#fafafa38", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 6}, "width": 28, "height": 28, "zIndex": 42, "frameId": "frame_page_1"}, {"x": 260, "y": 546.1117326, "id": "el_score_det_icon3_p1", "data": {"name": "FileWarning", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#ef4444", "padding": 3, "background": "#fafafa38", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 6}, "width": 28, "height": 28, "zIndex": 44, "frameId": "frame_page_1"}, {"x": 298, "y": 544.1117326, "id": "el_score_det_text3_p1", "data": {"text": "html:<span style='font-size:11px;font-weight:600;color:#1e293b;font-family:sans-serif;'>Probabilidade de inadimplência: {{calc(100 - $SCORE_CREDITO[0].score / 10 )}}%</span><br/><span style='color:#64748b;font-family:sans-serif;'>Estimativa de inadimplência — use como apoio à decisão.\\n</span>"}, "type": "text", "style": {"fontSize": 10, "lineHeight": 1.4}, "width": 440, "height": 29, "zIndex": 45, "frameId": "frame_page_1"}, {"x": 58.849162, "y": 597.6592184, "id": "el_score_ribbon_p1", "data": {"text": "html:<div style='display:flex;justify-content:space-between;margin:0;padding:6px 0;border-top:1px solid #f1f5f9;border-bottom:1px solid #f1f5f9;font-size:9px;font-family:sans-serif;box-sizing:border-box;'><div style='display:flex;align-items:center;gap:4px;'><span style='width:6px;height:6px;border-radius:50%;background:#dc2626;'></span><span style='font-weight:600;color:#1e293b;'>Péssimo</span> <span style='color:#64748b;'>0-200</span></div><div style='display:flex;align-items:center;gap:4px;'><span style='width:6px;height:6px;border-radius:50%;background:#ea580c;'></span><span style='font-weight:600;color:#1e293b;'>Ruim</span> <span style='color:#64748b;'>201-400</span></div><div style='display:flex;align-items:center;gap:4px;'><span style='width:6px;height:6px;border-radius:50%;background:#ca8a04;'></span><span style='font-weight:600;color:#1e293b;'>Regular</span> <span style='color:#64748b;'>401-600</span></div><div style='display:flex;align-items:center;gap:4px;'><span style='width:6px;height:6px;border-radius:50%;background:#65a30d;'></span><span style='font-weight:600;color:#1e293b;'>Bom</span> <span style='color:#64748b;'>601-800</span></div><div style='display:flex;align-items:center;gap:4px;'><span style='width:6px;height:6px;border-radius:50%;background:#16a34a;'></span><span style='font-weight:600;color:#1e293b;'>Ótimo</span> <span style='color:#64748b;'>801-1000</span></div></div>"}, "type": "text", "style": {}, "width": 694, "height": 28, "zIndex": 46, "frameId": "frame_page_1"}, {"x": 58.849162, "y": 632.3575424, "id": "el_score_interpret_p1", "data": {"text": "Hoje seu Score está em {{if($SCORE_CREDITO[0].score <= 200, 'Péssimo (0 a 200)', if($SCORE_CREDITO[0].score <= 400, 'Ruim (201 a 400)', if($SCORE_CREDITO[0].score <= 600, 'Regular (401 a 600)', if($SCORE_CREDITO[0].score <= 800, 'Bom (601 a 800)', 'Ótimo (801 a 1000)'))))}} — isso geralmente indica que o mercado enxerga {{if($SCORE_CREDITO[0].score <= 200, 'risco muito alto', if($SCORE_CREDITO[0].score <= 400, 'risco alto', if($SCORE_CREDITO[0].score <= 600, 'risco moderado', if($SCORE_CREDITO[0].score <= 800, 'risco baixo', 'risco muito baixo'))))}}. O objetivo aqui é identificar o que mais pesa na sua pontuação e montar o caminho mais rápido para destravar aprovações.\\n\\n"}, "type": "text", "style": {"color": "#334155", "fontSize": 10, "lineHeight": 1.4}, "width": 694, "height": 42, "zIndex": 47, "frameId": "frame_page_1"}, {"x": 60, "y": 672, "id": "el_score_influ_bg_p1", "data": {}, "type": "container", "style": {"background": "#f8fafc", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 8}, "width": 694, "height": 140, "zIndex": 48, "frameId": "frame_page_1"}, {"x": 75, "y": 687, "id": "el_score_influ_icon_p1", "data": {"name": "Activity", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#475569", "background": "transparent"}, "width": 22, "height": 22, "zIndex": 49, "frameId": "frame_page_1"}, {"x": 70, "y": 720, "id": "el_score_influ_body_p1", "data": {"text": "html:O Serasa Score é calculado por pilares. Os que mais pesam são hábitos de pagamento e experiência/relacionamento com o mercado — e dívidas negativadas também têm impacto alto, considerando inclusive o tempo desde a quitação.\\n\\n* Pagamentos em dia (cartão, parcelas e contas) têm peso alto na pontuação.\\n* Dívidas negativadas costumam derrubar o Score e demoram a perder impacto sem regularização.\\n* Muitas consultas/simulações de crédito em pouco tempo podem pesar negativamente (busca por crédito)."}, "type": "text", "style": {"color": "#475569", "fontSize": 11, "lineHeight": 1.4}, "width": 665, "height": 92, "zIndex": 50, "frameId": "frame_page_1"}, {"x": 60, "y": 825, "id": "el_score_diag_bg_p1", "data": {}, "type": "container", "style": {"background": "#ecfdf5", "borderColor": "#a7f3d0", "borderWidth": 1, "borderRadius": 8}, "width": 694, "height": 100, "zIndex": 51, "frameId": "frame_page_1"}, {"x": 72.9827759, "y": 844.1853846, "id": "el_score_diag_icon_p1", "data": {"name": "ShieldCheck", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#065f46"}, "width": 23, "height": 23, "zIndex": 52, "frameId": "frame_page_1"}, {"x": 40, "y": 1070, "id": "el_footer_p1", "data": {"text": "Consultas PRO — Relatório de Crédito • Página 1"}, "type": "text", "style": {"color": "#94a3b8", "fontSize": 8, "textAlign": "center"}, "width": 734, "height": 30, "zIndex": 56, "frameId": "frame_page_1"}, {"x": 40, "y": 1260, "id": "el_serasa_header_icon_p2", "data": {"name": "Database", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#334155", "background": "#f8fafc", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 6}, "widt