e_2"}, {"x": 230, "y": 1520, "id": "el_spc_header_div_p2", "data": {}, "type": "divider", "style": {"background": "#e2e8f0"}, "width": 440, "height": 2, "zIndex": 12, "frameId": "frame_page_2"}, {"x": 680, "y": 1510, "id": "el_spc_badge_p2", "data": {"text": "{{count($DIVIDAS_SPC.contrato)}} registros"}, "type": "text", "style": {"color": "#64748b", "padding": 4, "fontSize": 9, "textAlign": "center", "background": "#f8fafc", "fontWeight": 600, "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 999}, "width": 92, "height": 22, "zIndex": 13, "frameId": "frame_page_2"}, {"x": 87.93969949999999, "y": 839.9274862, "id": "text_vLS0v74C", "data": {"text": " Nós te ajudamos com tudo isso!"}, "name": "Texto", "type": "text", "style": {"color": "#065f46", "padding": 8, "fontSize": 11, "textAlign": "left", "fontFamily": "Inter, sans-serif", "fontWeight": 700, "lineHeight": 1.4}, "width": 223, "height": 31, "zIndex": 58, "binding": {"mode": "static"}, "frameId": "frame_page_1", "visible": true}, {"x": 67.9073077, "y": 865.1170513, "id": "text_nVyX2Bfz", "data": {"text": "O que trava crédito quase sempre é simples: pendência/negativação + histórico recente. A boa notícia é que, com estratégia, dá pra acelerar sua reabilitação e voltar a ser aprovado com mais facilidade.\\n"}, "name": "Texto", "type": "text", "style": {"color": "#065f46", "padding": 8, "fontSize": 13, "textAlign": "left", "fontFamily": "Inter, sans-serif", "fontWeight": 400, "lineHeight": 1.4}, "width": 674, "height": 52, "zIndex": 59, "binding": {"mode": "static"}, "frameId": "frame_page_1", "visible": true}, {"x": 100, "y": 680, "id": "text__5hEvfi3", "data": {"text": "O que mais influencia sua pontuação"}, "name": "Texto", "type": "text", "style": {"color": "#0f172a", "padding": 8, "fontSize": 14, "textAlign": "left", "fontFamily": "Inter, sans-serif", "fontWeight": 700, "lineHeight": 1.4}, "width": 287, "height": 36, "zIndex": 62, "binding": {"mode": "static"}, "frameId": "frame_page_1", "visible": true}, {"x": 57.6011514, "y": 951.589637, "id": "container_un2rHO6Q", "data": {}, "type": "container", "style": {"background": "#fdfded", "borderColor": "#eab3087a", "borderWidth": 1, "borderRadius": 8}, "width": 694, "height": 55, "zIndex": 63, "frameId": "frame_page_1"}, {"x": 77.62282990000001, "y": 969.8634873000001, "id": "icon_DQaxcllQ", "data": {"name": "CircleAlert", "strokeWidth": 1.5}, "type": "icon", "style": {"color": "#c27d05"}, "width": 22, "height": 22, "zIndex": 64, "frameId": "frame_page_1"}, {"x": 98.90271960000001, "y": 958.723832, "id": "text_38L2EySE", "data": {"text": "html:<b>Atenção</b>: score e faixas são indicadores estatísticos e não garantem aprovação de crédito. A decisão final é do credor. O objetivo deste relatório é analisar os motivos de negativa e identificar o que está impactando no seu crédito."}, "name": "Texto", "type": "text", "style": {"color": "#c27d05", "padding": 8, "fontSize": 10, "textAlign": "left", "fontFamily": "Inter, sans-serif", "fontWeight": 400, "lineHeight": 1.4}, "width": 642, "height": 44, "zIndex": 66, "binding": {"mode": "static"}, "frameId": "frame_page_1", "visible": true}, {"x": 30, "y": 1550, "id": "table_KGFLRQFf", "data": {"columns": [{"path": "data_inclusao", "label": "Inclusão"}, {"path": "data_vencimento", "label": "Vencimento"}, {"path": "Origem", "label": "Origem / Credor"}, {"path": "Contrato", "label": "Contrato"}, {"path": "valor", "label": "Valor (R$)", "format": "currency"}], "arrayPath": "$DIVIDAS_SPC", "autoHeight": true}, "type": "table", "style": {"background": "#ffffff", "borderColor": "#e2e8f0", "borderWidth": 1, "borderRadius": 12}, "width": 734, "height": 123, "zIndex": 67, "frameId": "frame_page_2"}, {"x": 294.3286486971516, "y": 506.7286848796109, "id": "text_EXcsOCJP", "data": {"text": "html:<span style='color:#64748b;font-family:sans-serif;'>Estimativa de adimplência nos próximos 6 meses.</span>"}, "name": "Texto", "type": "text", "style": {"color": "#0f172a", "padding": 8, "fontSiz